style.css:
@-moz-document url("https://www.youtube.com/") {
#contents.ytd-rich-grid-renderer {
    background-color: lightpink;
  }

  #masthead > #container {
    background-color: lightpink;
  }

  #chips {
    background-color: lightpink;
  }

  #guide-inner-content {
    background-color: lightpink;
  }

  #chips-content {
    background-color: lightpink;
  }

  #style-scope yt-chip-cloud-chip-renderer {
    background-color: #ffffff;
  }

  .ytd-mini-guide-renderer{
    background-color: lightpink;
  }

  #content > .style-scope:nth-child(4) {
    background-color: lightpink;
  }

  #left-arrow-button.ytd-feed-filter-chip-bar-renderer, #right-arrow-button.ytd-feed-filter-chip-bar-renderer {
    background-color: lightpink;
  }

  #right-arrow.ytd-feed-filter-chip-bar-renderer::before {
      background:linear-gradient(to left,lightpink 20%,rgba(255,255,255,0) 80%)
  }

  #left-arrow.ytd-feed-filter-chip-bar-renderer::after {
      background:linear-gradient(to right,lightpink 20%,rgba(255,255,255,0) 80%)
  }

  #header > .ytd-multi-page-menu-renderer {
     background-color: lightpink;
  }

  #sections > .ytd-multi-page-menu-renderer:nth-child(1) {
     background-color: lightpink;
  }

  #sections > .ytd-multi-page-menu-renderer:nth-child(2) {
     background-color: lightpink;
  }

  #sections > .ytd-multi-page-menu-renderer:nth-child(3) {
     background-color: lightpink;
  }

  #sections > .ytd-multi-page-menu-renderer:nth-child(4) {
     background-color: lightpink;
  }

  .ytd-multi-page-menu-renderer:nth-child(5) {
     background-color: lightpink;
  }

  ytd-post-renderer[uses-compact-lockup] {
    background-color: lightpink;
  }

  .watch-root-element {
     background-color: lightpink;
  }

  .ytSearchboxComponentInputBox {
    background-color: lightpink;
    box-shadow: inset 0 1px 2px lightpink;
  }

  .ytSearchboxComponentSearchButton {
      background-color: lightpink;
  }

  .yt-spec-icon-badge-shape__badge {
      border: 2px solid lightpink;
  }

  .ytd-page-manager:nth-child(4) {
      background-color: lightpink;
  }

  #page-header {
    background-color: lightpink;
  }
}
